        const block = document.createElement("span");
        block.className = "team-history-bio__leader";
        const label = document.createElement("small");
        label.textContent = entry[0];
        const value = document.createElement("strong");
        value.textContent = entry[3] === "savePct"
          ? (player.savePct ? player.name + " · " + player.savePct.toFixed(1).replace(".", ",") + " " + entry[2] : player.name)
          : player.name + " · " + player[entry[3]] + " " + entry[2];
        block.appendChild(label);
        block.appendChild(value);
        leaders.appendChild(block);
