  teamBioObserver.observe(document.documentElement, { childList: true, subtree: true });
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", enhanceTeamHistoryBio);
  else enhanceTeamHistoryBio();

  installImageRescueHook();

